    public static unsafe class ManacherOdd
    {
        public static void Run(byte* s, int len, int* radii)
        {
            int l = 0, r = -1;
            for (int i = 0; i < len; i++)
            {
                int k = i > r ? 1 : Math.Min(radii[l + r - i], r - i + 1);
                while (i - k >= 0 && i + k < len && s[i - k] == s[i + k]) k++;
                radii[i] = k--;
                if (i + k > r)
                {
                    l = i - k;
                    r = i + k;
                }
            }
        }
