            int i = 0;
            while (i < len)
            {
                int j = i + 1, k = i;
                while (j < len && s[k] <= s[j])
                {
                    if (s[k] < s[j]) k = i;
                    else k++;
                    j++;
                }
                while (i <= k)
                {
                    starts[count] = i;
                    lengths[count] = j - k;
                    count++;
                    i += j - k;
                }
            }
            return count;
        }
    }

    public static unsafe class MinCyclicShift
    {
        public static int Run(byte* s, int len)
        {
            if (len <= 1) return 0;
            int i = 0, j = 1, k = 0;
            while (i < len && j < len && k < len)
            {
                byte si = s[(i + k) % len];
                byte sj = s[(j + k) % len];
                if (si == sj) { k++; continue; }
                if (si > sj) i += k + 1;
                else j += k + 1;
                if (i == j) j++;
                k = 0;
            }
            return i < j ? i : j;
        }
    }

    public static unsafe class RunLengthEncode
    {
        public static int Run(byte* s, int len, byte* values, int* counts)
        {
