        {
            int* fail = stackalloc int[len];
            fail[0] = 0;
            for (int i = 1, j = 0; i < len; i++)
            {
                while (j > 0 && s[i] != s[j]) j = fail[j - 1];
                if (s[i] == s[j]) j++;
                fail[i] = j;
            }
            int p = len - fail[len - 1];
            return len % p == 0 ? p : len;
        }
