            fail[0] = 0;
            for (int i = 1, j = 0; i < len; i++)
            {
                while (j > 0 && s[i] != s[j]) j = fail[j - 1];
                if (s[i] == s[j]) j++;
                fail[i] = j;
            }
            int count = 0;
            int b = fail[len - 1];
            while (b > 0)
            {
                borders[count++] = b;
                b = fail[b - 1];
            }
            return count;
        }
    }

