        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static void Run(byte* ptr, int len, int* zPtr)
        {
            if (len <= 0) return;
            zPtr[0] = len;
            int l = 0, r = 0;
            for (int i = 1; i < len; i++)
            {
                if (i <= r)
                {
                    int k = i - l;
                    int rem = r - i + 1;
                    zPtr[i] = zPtr[k] < rem ? zPtr[k] : rem;
                }
                else
                {
                    zPtr[i] = 0;
