                while (i + zPtr[i] < len && ptr[zPtr[i]] == ptr[i + zPtr[i]])
                    zPtr[i]++;
                if (i + zPtr[i] - 1 > r)
                {
                    l = i;
                    r = i + zPtr[i] - 1;
                }
            }
