        {
            fail[0] = 0;
            for (int i = 1; i < len; i++)
            {
                int j = fail[i - 1];
                while (j > 0 && pattern[i] != pattern[j])
                    j = fail[j - 1];
                if (pattern[i] == pattern[j]) j++;
                fail[i] = j;
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static int Search(byte* text, int textLen, byte* pattern, int patLen, int* fail, int* matches)
        {
            int count = 0;
