            {
                while (j > 0 && text[i] != pattern[j])
                    j = fail[j - 1];
                if (text[i] == pattern[j]) j++;
                if (j == patLen)
                {
                    matches[count++] = i - patLen + 1;
                    j = fail[j - 1];
                }
            }
            return count;
        }
    }
